// A module that imports a local binding named `Object` shadows the
// global `Object` inside the precompiled-module functor body. Before
// the fix that threads `defineProperty` through the functor calling
// convention, the preamble's `Object.defineProperty(F,'name',...)`
// resolved against the imported value (here `() => null`), so the
// call evaluated to `(() => null).defineProperty(...)` (i.e.
// `undefined(...)`) and threw `TypeError` during functor evaluation.
//
// With the fix, the preamble uses the hidden binding threaded from the
// bundle runtime's `defineProperty`, which the runtime destructured
// from `globalThis.Object` before any user-source code runs.
import { Object } from 'object-dep';

export function F() {}

// Touch the imported binding to defeat any future dead-code elimination
// of the import-decl that does the shadowing.
export const shadowed = Object;
